//! Renamed, copied and oddly named paths, replayed from `fixtures/git-rename.jsonl`, generated by
//! `rust/tools/generate_vcs_rename_fixtures.mjs` from the original GitVcsDriverCore.ts and Diffs.ts.
//!
//! The original's status path reads plain (not `-z`) numstat and keeps what follows the first ` => `, so a
//! rename shown as `src/{util.ts => helpers.ts}` is reported as `helpers.ts}` beside the old path from the
//! porcelain entry. The port reproduces that exactly; the review and checkpoint diffs read `-z` output and
//! report the new path once. Each scenario is also built in a real repository and read by the driver.
mod common;

use common::{Repo, live_core};
use serde_json::{Value, json};
use t3_vcs::{
    checkpoint::parse_numstat_with_locale,
    review::parse_review_numstat,
    status::{LocalStatusOptions, parse_numstat_entries},
};

fn rows() -> Vec<Value> {
    include_str!("fixtures/git-rename.jsonl")
        .lines()
        .map(|line| serde_json::from_str(line).unwrap())
        .collect()
}

fn build(row: &Value) -> Repo {
    let repo = Repo::init();
    for (path, text) in row["base"].as_object().unwrap() {
        repo.write(path, text.as_str().unwrap());
    }
    repo.git(&["add", "-A"]);
    repo.git(&["commit", "-m", "base"]);
    for step in row["steps"].as_array().unwrap() {
        let step: Vec<&str> = step.as_array().unwrap().iter().map(|part| part.as_str().unwrap()).collect();
        match step[0] {
            "write" => repo.write(step[1], step[2]),
            "cp" => {
                std::fs::create_dir_all(repo.join(step[2]).parent().unwrap()).unwrap();
                std::fs::copy(repo.join(step[1]), repo.join(step[2])).unwrap();
            }
            "git" => {
                if step[1] == "mv" {
                    std::fs::create_dir_all(repo.join(step[3]).parent().unwrap()).unwrap();
                }
                repo.git(&step[1..]);
            }
            other => panic!("unknown step {other}"),
        }
    }
    repo
}

#[test]
fn every_reader_of_numstat_matches_the_original_for_renames_copies_and_odd_names() {
    let rows = rows();
    assert_eq!(rows.len(), 11);
    for row in &rows {
        let name = &row["name"];
        let entries: Vec<Value> = parse_numstat_entries(row["numstat"].as_str().unwrap()).into_iter().map(|entry| json!({"path": entry.path, "insertions": entry.insertions, "deletions": entry.deletions})).collect();
        assert_eq!(json!(entries), row["numstatEntries"], "{name}");
        assert_eq!(json!(parse_review_numstat(row["reviewZ"].as_str().unwrap())), row["review"], "{name}");
        let checkpoint: Vec<Value> = parse_numstat_with_locale(row["checkpointZ"].as_str().unwrap(), row["locale"].as_str().unwrap())
            .into_iter()
            .map(|file| json!({"path": file.path, "additions": file.additions, "deletions": file.deletions}))
            .collect();
        assert_eq!(json!(checkpoint), row["checkpoint"], "{name}");
        // The `-z` readers report one path per rename: its destination.
        for file in row["review"].as_array().unwrap() {
            assert!(!file["path"].as_str().unwrap().contains('}'), "{name}: {file}");
        }
    }
}

#[tokio::test]
async fn status_of_a_real_repository_reports_what_the_original_reports() {
    for row in rows() {
        let name = row["name"].clone();
        let repo = build(&row);
        let status = live_core()
            .status_details_local(repo.path(), LocalStatusOptions::default())
            .await
            .unwrap();
        let expected = &row["workingTree"];
        let mut actual: Vec<Value> = status
            .working_tree
            .files
            .iter()
            .map(|file| json!({"path": file.path, "insertions": file.insertions, "deletions": file.deletions}))
            .collect();
        let mut wanted = expected["files"].as_array().unwrap().clone();
        // The order is the process locale's; what is reported is not.
        let by_path = |left: &Value, right: &Value| left["path"].as_str().cmp(&right["path"].as_str());
        actual.sort_by(by_path);
        wanted.sort_by(by_path);
        assert_eq!(actual, wanted, "{name}");
        assert_eq!(status.working_tree.insertions, expected["insertions"].as_u64().unwrap(), "{name}");
        assert_eq!(status.working_tree.deletions, expected["deletions"].as_u64().unwrap(), "{name}");
        assert_eq!(status.has_working_tree_changes, expected["hasWorkingTreeChanges"], "{name}");
    }
}
